import { showModal } from '@ui-kit/Modal';

import RoutePartModal from './components/RoutePartModal';
import RoutePartsModal from './components/RoutePartsModal';

export function routePartModal({ id_route_object }: { id_route_object: number }) {
  showModal({
    size: 'sm',
    children: <RoutePartModal id_route_object={id_route_object} />,
  });
}
export function routePartsModal({
  route_object_ids,
  id_route,
}: {
  route_object_ids: number[];
  id_route: number;
}) {
  showModal({
    size: 'sm',
    children: <RoutePartsModal route_object_ids={route_object_ids} id_route={id_route} />,
  });
}

export default routePartModal;
