import { IGetFoodLoadCriteria } from '@apps/Hiking/@services/hikingMenu.service';
import { showModal } from '@ui-kit/Modal';

import FoodActModal from './FoodActModal';

export function foodActModal({
  id_act,
  date,
  id_hiking,
  title,
}: IGetFoodLoadCriteria & { title: string }) {
  showModal({
    title,
    children: <FoodActModal id_act={id_act} date={date} id_hiking={id_hiking} />,
  });
}

export default foodActModal;
