import React from 'react';

import { getFoodAsync, IGetFoodLoadCriteria } from '@apps/Hiking/@services/hikingMenu.service';
import { IHikingMenuFood } from '@apps/Hiking/@types/hikingMenu.types';
import BGU from '@components/BGU';
import PageLoader from '@components/PageLoader';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohIcon from '@ui-kit/Icon';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohList from '@ui-kit/List';

const FoodActModal = ({ id_act, id_hiking, date }: IGetFoodLoadCriteria) => {
  const [data, setData] = React.useState<IHikingMenuFood[] | null>(null);
  React.useEffect(() => {
    getFoodAsync({ id_act, id_hiking, date }).then(setData);
  }, []);

  if (data == null) {
    return <PageLoader />;
  }

  if (data.length === 0) {
    return <Empty>Пока не понятно :(</Empty>;
  }

  return (
    <PohList
      data={data.map((x) => ({
        key: x.id,
        content: (
          <div>
            <small className="float-end">
              <BGU
                portion={x.amount}
                protein={x.proteins}
                fat={x.fats}
                carbohydrates={x.carbs}
                energy={x.energy}
                unit="g"
              />
            </small>
            {x.name}
            <PohButton
              className="ms-2"
              as="a"
              href={`/recipes/${x.id_recipe}`}
              target="_blank"
              title="Подробнее/Рецепт"
              variant={ButtonVariant.Light}
              size={ButtonSize.Small}
            >
              <PohIcon name={IconsEnum.open} />
            </PohButton>
          </div>
        ),
      }))}
    />
  );
};

export default FoodActModal;
